fn multiplyUint64(left: vec2<u32>, right: vec2<u32>) -> vec2<u32> {
  let wide = multiplyUint32Wide(left.y, right.y);
  return vec2<u32>(wide.x + left.y * right.x + left.x * right.y, wide.y);
