fn philoxMulHiLo(a: u32, b: u32) -> vec2<u32> {
  let aLow = a & 0xffffu;
  let aHigh = a >> 16u;
  let bLow = b & 0xffffu;
  let bHigh = b >> 16u;
  let lowLow = aLow * bLow;
  let highLow = aHigh * bLow;
  let lowHigh = aLow * bHigh;
  let highHigh = aHigh * bHigh;
  let middle = (lowLow >> 16u) + (highLow & 0xffffu) + (lowHigh & 0xffffu);
  let high = highHigh + (highLow >> 16u) + (lowHigh >> 16u) + (middle >> 16u);
  return vec2<u32>(high, a * b);
}

fn philoxRound(counter: vec4<u32>, key: vec2<u32>) -> vec4<u32> {
  let product0 = philoxMulHiLo(3528531795u, counter.x);
  let product1 = philoxMulHiLo(3449720151u, counter.z);
  return vec4<u32>(
    product1.x ^ counter.y ^ key.x,
    product1.y,
    product0.x ^ counter.w ^ key.y,
    product0.y
  );
}

fn philox4x32(counterIn: vec4<u32>, keyIn: vec2<u32>) -> vec4<u32> {
  var counter = counterIn;
  var key = keyIn;
  for (var roundIndex = 0u; roundIndex < 9u; roundIndex = roundIndex + 1u) {
    counter = philoxRound(counter, key);
    key = key + vec2<u32>(2654435769u, 3144134277u);
  }
  return philoxRound(counter, key);
}

fn philoxUnitFloat(word: u32) -> f32 {
  return f32(word >> 8u) * (1.0 / 16777216.0);
}

// Uniform in the open interval (0, 1), for log() and inverse-CDF draws. The top 23 bits plus one
// half are exact in f32, so the result lies in [2^-24, 1 - 2^-24] and neither end is reachable.
// (The 24-bit form (f32(word >> 8u) + 0.5) / 16777216.0 rounds to exactly 1.0 for the largest word.)
fn philoxOpenUnitFloat(word: u32) -> f32 {
  return (f32(word >> 9u) + 0.5) * (1.0 / 8388608.0);
}


fn getPhiloxMultiplyHigh(a: u32, b: u32) -> u32 {
  return philoxMulHiLo(a, b).x;
}

fn getPhilox4x32(counter: vec4<u32>, key: vec2<u32>) -> vec4<u32> {
  return philox4x32(counter, key);
}

struct PhiloxStream {
  key: vec2<u32>,
  words: vec3<u32>,
  block: u32,
  lane: u32,
  buffer: vec4<u32>
}

fn createPhiloxStream(key: vec2<u32>, a: u32, b: u32, c: u32) -> PhiloxStream {
  var stream: PhiloxStream;
  stream.key = key;
  stream.words = vec3<u32>(a, b, c);
  stream.block = 0u;
  stream.lane = 4u;
  stream.buffer = vec4<u32>(0u);
  return stream;
}

fn nextPhiloxUint32(stream: ptr<function, PhiloxStream>) -> u32 {
  if ((*stream).lane == 4u) {
    (*stream).buffer = getPhilox4x32(
      vec4<u32>((*stream).block, (*stream).words.x, (*stream).words.y, (*stream).words.z),
      (*stream).key
    );
    (*stream).block = (*stream).block + 1u;
    (*stream).lane = 0u;
  }
  let word = (*stream).buffer[(*stream).lane];
  (*stream).lane = (*stream).lane + 1u;
  return word;
}

fn nextPhiloxBelow(stream: ptr<function, PhiloxStream>, bound: u32) -> u32 {
  var value = nextPhiloxUint32(stream);
  var low = value * bound;
  if (low < bound) {
    let threshold = (0u - bound) % bound;
    while (low < threshold) {
      value = nextPhiloxUint32(stream);
      low = value * bound;
    }
  }
  return getPhiloxMultiplyHigh(value, bound);
}

const RANDOM_TAG: u32 = 68769u;

// Value at a virtual shuffle position: a recorded swap, or the position itself.
fn readSwap(
  swapPositions: ptr<function, array<u32, 4>>,
  swapValues: ptr<function, array<u32, 4>>,
  swapCount: u32,
  position: u32
) -> u32 {
  for (var entry = 0u; entry < swapCount; entry++) {
    if ((*swapPositions)[entry] == position) {
      return (*swapValues)[entry];
    }
  }
  return position;
}
@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) workgroupId: vec3<u32>,
  @builtin(num_workgroups) workgroupCount: vec3<u32>,
  @builtin(local_invocation_index) localInvocationIndex: u32) {
  let workgroupIndex = (workgroupId.z * workgroupCount.y + workgroupId.y) * workgroupCount.x + workgroupId.x;
  if (workgroupIndex >= 16777216u) { return; }
  let index = workgroupIndex * 256u + localInvocationIndex;
  if (index >= getChunkParameter(1u)) { return; }
  offsetsOffset = getChunkParameter(4u);
  neighborsOffset = getChunkParameter(5u);
  weightsOffset = getChunkParameter(6u);
  rowPositionsOffset = getChunkParameter(7u);
  pairsOffset = getChunkParameter(8u);
  parametersOffset = getChunkParameter(9u);
  observedRawOffset = getChunkParameter(10u);
  exceedancesOffset = getChunkParameter(11u);
  CAPACITY = arrayLength(&neighbors) - neighborsOffset;
  WEIGHTS_ROW_START = getChunkParameter(36u);
  { let index = index + getChunkParameter(0u);
  let observed = observedRaw[observedRawOffset + index];
  // The permutation count is never clamped: an invalid one leaves every row untested.
  // Join counts test only rows with at least one join (esda sets the other p-values to NaN).
  if (!isFiniteFloat(observed) || !isPermutationCountValid() || observed == 0.0) {
    exceedances[exceedancesOffset + index] = NOT_TESTED;
    return;
  }
  let position = rowPositions[rowPositionsOffset + index];
  let others = rowPositions[rowPositionsOffset + ROWS] - 1u;
  let fx = getX(position);
  let fy = getY(position);
  let permutations = readValidPermutationCount();
  let key = readSeedKey();
  var greater = 0u;
  var lesser = 0u;
  var folded = 0u;
  var total = 0.0;
  var mean = 0.0;
  // The row's active neighbor weights in slot order, read once: a permutation only reassigns
  // values to slots, so the per-draw work is the random draw and one value gather, not four
  // CSR gathers (offsets, neighbor, neighbor position, weight) per slot per permutation.
  var slotWeights: array<f32, 4>;
  var neighborTotal = 0u;
  {
    let activeRow = index;
    let activeBegin = min(offsets[offsetsOffset + activeRow - (WEIGHTS_ROW_START)], CAPACITY);
    let activeEnd = min(offsets[offsetsOffset + activeRow - (WEIGHTS_ROW_START) + 1u], CAPACITY);
    for (var slot = activeBegin; slot < activeEnd; slot++) {
      let neighbor = neighbors[neighborsOffset + slot];
      if (neighbor >= ROWS || neighbor == activeRow) {
        continue;
      }
      let weight = weights[weightsOffset + slot];
      if (!(weight > 0.0) || !(rowPositions[rowPositionsOffset + neighbor] != INVALID_POSITION)) {
        continue;
      }
      if (neighborTotal < MAXIMUM_NEIGHBORS) {
      slotWeights[neighborTotal] = 1.0;
      neighborTotal++;
    }
    }
  }
  // Islands (kept) and rows that cannot draw k distinct others are not tested.
  if (neighborTotal == 0u || neighborTotal > others) {
    exceedances[exceedancesOffset + index] = NOT_TESTED;
    return;
  }
  // 'folded' needs the simulated mean first: sweep 0 sums, sweep 1 counts (same deterministic stream).
  for (var sweep = 0u; sweep < 1u; sweep++) {
  for (var permutation = 0u; permutation < permutations; permutation++) {
    var stream = createPhiloxStream(key, index, permutation, RANDOM_TAG);
    var swapPositions: array<u32, 4>;
    var swapValues: array<u32, 4>;
    var swapCount = 0u;
    var lagA = 0.0;
    var lagB = 0.0;
    for (var drawn = 0u; drawn < neighborTotal; drawn++) {
      // Partial Fisher-Yates over the other analysis rows' virtual positions [0, others).
      let pick = drawn + nextPhiloxBelow(&stream, others - drawn);
      let chosen = readSwap(&swapPositions, &swapValues, swapCount, pick);
      if (pick != drawn) {
        let displaced = readSwap(&swapPositions, &swapValues, swapCount, drawn);
        var entry = 0u;
        loop {
          if (entry == swapCount || swapPositions[entry] == pick) {
            break;
          }
          entry++;
        }
        swapPositions[entry] = pick;
        swapValues[entry] = displaced;
        swapCount = max(swapCount, entry + 1u);
      }
      let drawnPosition = chosen + select(0u, 1u, chosen >= position);
      let dx = getX(drawnPosition);
      let dy = getY(drawnPosition);
      lagA += slotWeights[drawn] * getDrawnA(fx, fy, dx, dy);

    }
    let simulated = getLocalTerm(fx, fy, lagA, lagB);
    greater += select(0u, 1u, simulated >= observed);
    lesser += select(0u, 1u, simulated <= observed);
  }
  mean = total / f32(permutations);
  }
  exceedances[exceedancesOffset + index] = min(greater, lesser);
  }
}

