  let significand = fraction | select(0u, 0x800000u, exponent != 0u);
  if (significand == 0u) { return bitcast<f32>(negative | 0x7f800000u); }
  let division = divideUint64ByUint32(vec2<u32>(count, 0u), significand);
  return roundSpatialCountValue(division.quotient, 118i - i32(max(exponent, 1u)),
    negative, division.remainder != 0u);
}

fn divideSpatialCounts(numerator: u32, denominator: u32) -> f32 {
  if (numerator <= 16777216u && denominator <= 16777216u) { return f32(numerator) / f32(denominator); }
  if (numerator == 0u) { return 0.0; }
  let shift = 31u + countLeadingZeros(numerator);
  let division = divideUint64ByUint32(shiftLeftUint64(vec2<u32>(0u, numerator), shift), denominator);
  return roundSpatialCountValue(division.quotient, -i32(shift), 0u, division.remainder != 0u);
}



// A runtime operand keeps the quiet-NaN bit pattern out of constant evaluation.

fn getQuietNaN(seed: u32) -> f32 { return bitcast<f32>(0x7fc00000u | (seed & 0u)); }


// Two-sided normal p-value erfc(|z| / sqrt(2)) through the shared erfcValue (Numerical Recipes
// erfcc Chebyshev fit, fractional error below 1.2e-7), so tiny p-values keep relative accuracy.

fn erfcValue(x: f32) -> f32 {
  let z = abs(x);
  let t = 1.0 / (1.0 + 0.5 * z);
  let r = t * exp(-z * z - 1.26551223 + t * (1.00002368 + t * (0.37409196 + t * (0.09678418 +
    t * (-0.18628806 + t * (0.27886807 + t * (-1.13520398 + t * (1.48851587 +
    t * (-0.82215223 + t * 0.17087277)))))))));
  return select(2.0 - r, r, x >= 0.0);
}


// Floor of every analytic (normal) p-value: the smallest normal f32. f32 exp underflows beyond
// |z| of about 13, where erfc would read exactly 0; a floor keeps such p-values positive, so they
// stay ordered against larger ones in a multiple-testing correction and safe under log(). One
// rule for the global, local, hot-spot and emerging-hot-spot statistics.
const ANALYTIC_P_VALUE_FLOOR: f32 = 1.17549435e-38;

fn getTwoSidedPValue(z: f32) -> f32 {
  return clamp(erfcValue(abs(z) * 0.70710678118654752), ANALYTIC_P_VALUE_FLOOR, 1.0);
}

// A binary join-count variable: exactly 1 is a join, anything else is 0.
fn isOne(value: f32) -> f32 {
  return select(0.0, 1.0, value == 1.0);
}
// The statistic up to a positive per-row constant; identical for observed and simulated terms.
fn getLocalTerm(fx: f32, fy: f32, lagA: f32, lagB: f32) -> f32 {
  return isOne(fx) * isOne(fy) * lagA;
